def solution(user_flags, flag_review):
    import pandas as pd

    merged = user_flags.merge(flag_review, on='flag_id')
    filtered = merged[merged['reviewed_by_yt'] == True]

    result = filtered.groupby(['user_firstname', 'user_lastname']).apply(
        lambda group: pd.Series({
            'videos_flagged': group['video_id'].nunique(),
            'videos_removed': group[group['reviewed_outcome'].str.lower() == 'removed']['video_id'].nunique(),
            'latest_review_date': group['reviewed_date'].max()
        })
    ).reset_index()
    return result

