solution_polars:
import polars as pl


def pl_solution(df: pl.LazyFrame) -> pl.DataFrame:
    return (
        df.group_by_dynamic("created_at", every="1mo")
        .agg(monthly_revenue=(pl.col("value").sum()))
        .with_columns(
            created_at=pl.col("created_at").dt.strftime("%Y-%m"),
            revenue_pct_change=pl.col("monthly_revenue").pct_change().mul(100).round(2),
        )
        .select(["created_at", "revenue_pct_change"])
    )

sf_transactions.pipe(pl_solution)

solution_python:
def solution(fraud_score):
    import pandas as pd

    fraud_score = fraud_score.assign(
        threshold=fraud_score.groupby("state")["fraud_score"].transform(
            lambda x: x.quantile(0.95)
        )
    )

    result = fraud_score[fraud_score["fraud_score"] >= fraud_score["threshold"]][
        ["policy_num", "state", "claim_cost", "fraud_score"]
    ]

solution_polars:
import polars as pl

result = (
    fb_search_events.lazy()
    .select([
        (
            (
                (pl.col("search_results_position") <= 3) &
                (pl.col("clicked") == 1)
            ).cast(pl.Int8).sum() / pl.count() * 100
        ).alias("top_3_clicked"),
        (
            (
                (pl.col("search_results_position") <= 3) &
                (pl.col("clicked") == 0)
            ).cast(pl.Int8).sum() / pl.count() * 100
        ).alias("top_3_notclicked")
    ])
    .collect()
)

