def solution(billboard_top_100_year_end):
    result = billboard_top_100_year_end[
        (billboard_top_100_year_end['year'] >= 2005) &
        (billboard_top_100_year_end['year_rank'] == 1)
    ][['song_name']].drop_duplicates().reset_index(drop=True)
    return result

def solution(sf_restaurant_health_violations):    
    import pandas as pd

    def extract_street(address):
        parts = str(address).split()
        if len(parts) < 2:
            return ''
        if parts[0].isdigit():
            return parts[1].lower()
        elif len(parts) > 1 and parts[1].isdigit():
            return parts[0].lower()
        return parts[0].lower()

    sf_restaurant_health_violations['street_name'] = sf_restaurant_health_violations['business_address'].apply(extract_street)

    result = (
        sf_restaurant_health_violations
        .loc[sf_restaurant_health_violations['business_postal_code'].notna()]
        .groupby('business_postal_code')['street_name']
        .nunique()
        .reset_index(name='n_streets')
        .sort_values(by=['n_streets', 'business_postal_code'], ascending=[False, True])
    )
    return result

solution_r:
library(dplyr)
library(stringr)

extract_street <- function(address) {
  parts <- str_split(address, "\\s+")[[1]]
  if (length(parts) < 2) return("")
  if (str_detect(parts[1], "^[0-9]+$")) return(tolower(parts[2]))
  if (length(parts) > 1 && str_detect(parts[2], "^[0-9]+$")) return(tolower(parts[1]))
  return(tolower(parts[1]))
}

result <- sf_restaurant_health_violations %>%
  filter(!is.na(business_postal_code)) %>%
  rowwise() %>%
  mutate(street_name = extract_street(business_address)) %>%
  ungroup() %>%
  group_by(business_postal_code) %>%
  summarise(n_streets = n_distinct(street_name)) %>%
  arrange(desc(n_streets), business_postal_code)

solution_pyspark:
from pyspark.sql.functions import col, lower, regexp_extract, when, countDistinct

cte1 = sf_restaurant_health_violations.withColumn(
    "street_name",
    lower(
        when(
            col("business_address").rlike(r"^[0-9]+"),
            regexp_extract(col("business_address"), r"^[0-9]+\s+([^\s]+)", 1)
        ).when(
            col("business_address").rlike(r"^\S+\s+[0-9]+"),
            regexp_extract(col("business_address"), r"^([^\s]+)", 1)
        ).otherwise(
            regexp_extract(col("business_address"), r"^([^\s]+)", 1)
        )
    )
).select(
    "street_name", col("business_postal_code").alias("postal_code")
)

result = cte1.filter(
    col("postal_code").isNotNull()
).groupBy(
    "postal_code"
).agg(
    countDistinct("street_name").alias("n_streets")
).orderBy(
    col("n_streets").desc(), col("postal_code").asc()
).toPandas()
